export default function generateFuelLimitedGlobals(semant, state, fuelLimit = 100) {
    if (!Number.isSafeInteger(fuelLimit) || fuelLimit < 1) {
        throw new TypeError("The autograder fuel limit must be a positive safe integer.");
    }

    const nodes = state.get("nodes");
    const globals = state.get("globals");
    const globalNames = new Set(globals.keySeq().toArray());
    let applyFuelName = "__reductApplyFuel";
    while (globalNames.has(applyFuelName)) {
        applyFuelName += "_";
    }

    let source = `let t = ${fuelLimit};
function ${applyFuelName}(fn, args, arity, applied = 0) {
  for (const arg of args) {
    if (typeof fn !== "function") {
      throw new TypeError("Too many arguments supplied to a Reduct function.");
    }
    if (applied === arity - 1) {
      t--;
      if (t < 0) return -100000;
    }
    fn = fn(arg);
    applied++;
  }
  if (applied >= arity) return fn;
  return (argument) => ${applyFuelName}(fn, [ argument ], arity, applied);
}
`;

    for (const [ name, defId ] of globals) {
        const definition = nodes.get(defId);
        if (!definition || definition.get("type") !== "define") {
            throw new TypeError(`Global '${name}' is not a function definition.`);
        }

        const definitionSource = semant.parser.unparse(semant.hydrate(nodes, definition));
        const definitionPattern =
            /^function\s+([a-zA-Z_$][\w$]*)\s*\(\)\s*\{\s*return\s+([\s\S]*);\s*\}$/;
        const match = definitionSource.match(definitionPattern);
        if (!match) {
            throw new TypeError(`Could not generate JavaScript for global '${name}'.`);
        }

        const [ , functionName, functionBody ] = match;
        const arity = (definition.get("params") || []).length;
        if (functionName !== name) {
            throw new TypeError(`Global name '${name}' does not match its definition.`);
        }

        if (arity === 0) {
            source += `function ${functionName}(...args) {
  if (args.length > 0) {
    throw new TypeError("Too many arguments supplied to a Reduct function.");
  }
  t--;
  if (t < 0) return -100000;
  return (${functionBody});
}
`;
        }
        else {
            source += `function ${functionName}(...args) {
  return ${applyFuelName}((${functionBody}), args, ${arity});
}
`;
        }
    }

    return source;
}
